// grow_with_claudinite task: growth-extract — the growth lifecycle's CAPTURE
// stage (per-project-scheduling DESIGN §6). ONE task over BOTH lesson sources:
// it runs the extract-from-activity skill over the window's commits/PRs/issues
// and the extract-from-conversations skill over the captured conversation logs,
// then runs prose-to-checks over what it just wrote to see whether any of it
// upgrades to a check — and lands the whole run through a single PR delivered
// per the repo's delivery settings (task.md → the shared deliver-pr.md
// procedure). Worker: task.md.
//
// The two halves were separate tasks (growth-extract + conversation-extract)
// firing in the same daily slot, each opening its own PR against the same local
// packs on the same night. They shared the lesson bar, the promotion ladder, the
// dedup surface and the landing mechanics, so splitting them bought nothing and
// cost a second opus dispatch, a second PR, and two runs deduping against a
// corpus the other one was concurrently writing. One task, two source skills.
//
// Self-contained (imports nothing): the whole contract is this default export.

export default {
  id: 'growth-extract',
  frequency: 'daily-1h',           // the 03:00 slot — lessons captured from an already-converged mount (DESIGN §2)
  // …and, where the repo dispatches through the work-item queue, the ordering the
  // anchor hour only IMPLIES, declared (tasks-dispatch DESIGN §9): this task reads
  // a mount `core/update` converges, so it yields while that task's item is live
  // this cycle and runs the moment it converges — or rolls. Ignored under slot
  // dispatch, where the staggered anchors carry the same intent.
  after: ['core/update'],
  precondition_signals: ['commits', 'prs', 'issues', 'conversationLogs'],
  agent_model: 'opus',                   // generalizing/curating lessons is the heaviest judgment, and the default delivery lands the PR with no human review
  expected_outcome: 'merged-pr',            // additive edits to the repo's own local packs; delivered to land per the repo's delivery settings
  agent_instructions: 'task.md',
  agent_execution_timeout: 2700,            // two source passes plus the prose-to-checks upgrade — generous bound, extreme protection

  // TWO independent reasons to run, and the Context says which halves are live:
  //
  //   (a) a SUBSTANTIVE default-branch change — a bot bump / [skip ci] /
  //       nightly-baselining commit advancing main is not a lesson to extract, so
  //       `commits.substantiveChange` already applies that classification. This
  //       arms the activity half AND means a fresh capture now sits on the logs
  //       branch, so the conversation half runs too.
  //   (b) a log on the branch is ACTUALLY past retention — aged material to give a
  //       final hindsight pass and prune, regardless of activity, so the prune
  //       still fires on a quiet repo (a log ages out on wall time, not on the
  //       repo changing). (b) tests the AGE, not just "a branch exists and
  //       retention is configured": that pair is true on every capturing repo
  //       every day, which dispatched an opus agent daily to find nothing prunable.
  //
  // The activity half is scoped by the substantive shas + touched PR/issue numbers
  // passed as binding scope — INCLUDING the PRs merged during the window, whose
  // review discussion is usually its richest lesson source. Context is binding
  // scope and task.md forbids widening past it, so a merged PR the precondition
  // does not name is unreadable to the worker. When only (b) fired, Context says
  // so explicitly, so a quiet-but-aged run skips the activity half rather than
  // inventing a window for it.
  precondition(signals) {
    const commits = signals.commits ?? {};
    const substantive = commits.substantiveChange === true;
    const logs = signals.conversationLogs ?? {};
    const retention = logs.retentionDays;
    const oldest = logs.oldestLogAgeDays;
    const configured = logs.present === true && typeof retention === 'number';
    const aged = configured && typeof oldest === 'number' && oldest > retention;

    if (!substantive && !aged) {
      if (configured) return { run: false, reason: `no substantive default-branch change and no log older than retention ${retention}d — nothing to extract or prune` };
      return { run: false, reason: logs.present ? 'no substantive default-branch change and retention unset — nothing to extract or prune' : 'no substantive default-branch change and no logs branch' };
    }

    const context = [];
    const reasons = [];

    if (substantive) {
      const shas = (commits.list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
      const prs = signals.prs?.touched ?? [];
      const merged = (signals.prs?.merged ?? []).map((p) => p.number);
      const issues = signals.issues?.touched ?? [];
      reasons.push(`${shas.length} substantive commit(s) in the window`);
      context.push(`Activity half IS in scope: the ${shas.length} substantive commit(s) in the window — ${shas.join(', ')}.`);
      if (merged.length) context.push(`PRs merged in the window — read each one's diff and its review discussion: ${merged.map((n) => `#${n}`).join(', ')}.`);
      if (prs.length) context.push(`PRs touched in the window: ${prs.map((n) => `#${n}`).join(', ')}.`);
      if (issues.length) context.push(`Issues touched in the window: ${issues.map((n) => `#${n}`).join(', ')}.`);
      context.push('Conversation half IS in scope: a substantive merge means fresh captures on origin/conversation-logs — run the fresh pass over the recent window.');
    } else {
      context.push('Activity half is NOT in scope: no substantive default-branch change in the window. Skip extract-from-activity entirely — do not invent a window for it.');
    }

    if (aged) {
      reasons.push(`oldest log ${oldest.toFixed(1)}d old vs retention ${retention}d`);
      context.push(`Retention prune IS due: the oldest log is ${oldest.toFixed(1)}d old against retention ${retention}d. Every log past ${retention}d gets its final hindsight pass, then is removed from the logs branch.`);
    } else if (substantive && configured) {
      context.push(`Retention prune is NOT due: no log is older than retention ${retention}d. Delete nothing.`);
    } else if (substantive) {
      context.push('Retention prune is NOT due: retention is unset for this repo. Delete nothing (capture-only adoption).');
    }

    return { run: true, reason: reasons.join('; '), context };
  },
};

// The task-janitor's prework — the whole task (agent_model: none). The ONE
// home of dispatch-issue recovery and health review, moved out of the
// scheduler's hourly run (owner, 2026-08-06: scheduler creates, executor
// executes its one issue, janitor cleans up). This file is the I/O shell; the
// verdicts are the pure rules in the vendored engine (dispatch.mjs), so what
// counts as stale, dead or lost is decided in exactly one place.
//
// Three backstops, in this order:
//   1. STALE — a dispatch open past ~2 of its own scheduling periods →
//      escalation comment, drop the ready label, add `needs-human`. Once — an
//      already-escalated issue is never re-announced.
//   2. DEAD CLAIM — `agent-running` with no activity for ~3h → the session that
//      claimed it died; comment, drop `agent-running`, add `needs-human`.
//   3. RE-ARM — armed but untouched past the grace window → the trigger event
//      was lost, so remove and re-add its ready label to emit a fresh one.
// Stale wins over re-arm, so an issue converging to triage is never put back
// into circulation.
//
// The daily cadence is a stated trade (it was hourly when it lived in the
// scheduler): a lost trigger event or a dead claim now waits up to a day for
// recovery. That is the price of the responsibility split, and the owner chose
// it — recurring recovery is cleanup, and cleanup is nobody's job but this one.
//
// It ends with a HEALTH REVIEW: one line per open dispatch state, so the run
// log answers "how is the task machinery doing" at a glance.

import { pathToFileURL } from 'node:url';
import {
  staleDispatchIssues, staleEscalationComment, staleClaimedDispatchIssues, staleClaimComment,
  rearmDispatchIssues, readyLabelOn, DISPATCH_PREFIX, NEEDS_HUMAN_LABEL, AGENT_RUNNING_LABEL,
  SCHEDULER_LABELS,
} from '../../../../engine/scheduler/dispatch.mjs';
import { makeGh } from '../../../../engine/scheduler/signals/gh.mjs';
import { ensureLabels } from '../../../../engine/scheduler/run.mjs';

const slotId = process.env.CLAUDINITE_SLOT_ID || '';
const log = (s) => console.log(`task-janitor${slotId ? ` [${slotId}]` : ''}: ${s}`);

// Every OPEN dispatch issue in the repo, with the labels / age / comment count
// the rules read. Repo-wide and open-only — the scheduler's own per-family
// state=all search (its filing guards) is a different question.
export async function openDispatchIssues(gh, repo) {
  const q = encodeURIComponent(`repo:${repo} is:issue is:open in:title "${DISPATCH_PREFIX}"`);
  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
  if (status !== 200 || !Array.isArray(json?.items)) {
    throw new Error(`could not list open dispatch issues: search returned ${status}`);
  }
  return json.items.map((i) => ({
    number: i.number, title: i.title, labels: i.labels ?? [],
    created_at: i.created_at, updated_at: i.updated_at, comments: i.comments ?? 0,
  }));
}

// The sweep, injectable for tests: `gh` is the Action-token REST client.
export async function sweep(gh, repo, now) {
  const open = await openDispatchIssues(gh, repo);
  const result = { open: open.length, stale: [], deadClaims: [], rearmed: [] };
  const stale = staleDispatchIssues(open, now);
  const staleNumbers = new Set(stale.map((i) => i.number));
  const deadClaims = staleClaimedDispatchIssues(open, now).filter((i) => !staleNumbers.has(i.number));
  const rearm = rearmDispatchIssues(open, now);

  if (stale.length || deadClaims.length || rearm.length) {
    // Applying a label 422s when it does not exist, so guarantee them first — a
    // quiet repo never gets here, so this costs nothing on the common path.
    await ensureLabels(gh, repo, SCHEDULER_LABELS);
  }

  const escalate = async (issue, body, dropLabel) => {
    await gh(`/repos/${repo}/issues/${issue.number}/comments`, { method: 'POST', body: { body } });
    if (dropLabel) await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(dropLabel)}`, { method: 'DELETE' });
    await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [NEEDS_HUMAN_LABEL] } });
  };

  for (const issue of stale) {
    await escalate(issue, staleEscalationComment(issue), readyLabelOn(issue));
    log(`escalated stale dispatch #${issue.number} to ${NEEDS_HUMAN_LABEL}`);
    result.stale.push(issue.number);
  }
  for (const issue of deadClaims) {
    await escalate(issue, staleClaimComment(issue), AGENT_RUNNING_LABEL);
    log(`reclaimed dead ${AGENT_RUNNING_LABEL} claim on #${issue.number} → ${NEEDS_HUMAN_LABEL}`);
    result.deadClaims.push(issue.number);
  }
  for (const issue of rearm) {
    const ready = readyLabelOn(issue);
    const del = await gh(`/repos/${repo}/issues/${issue.number}/labels/${encodeURIComponent(ready)}`, { method: 'DELETE' });
    if (del.status >= 300) { log(`! could not un-label #${issue.number} to re-arm it: ${del.status}`); continue; }
    const add = await gh(`/repos/${repo}/issues/${issue.number}/labels`, { method: 'POST', body: { labels: [ready] } });
    if (add.status >= 300) log(`! re-arm of #${issue.number} dropped its ${ready} label: ${add.status}`);
    else { log(`re-armed #${issue.number} (${ready}) — its trigger event never landed`); result.rearmed.push(issue.number); }
  }

  // The health review — the "reviews status, assesses health" half. Counts are
  // over the post-sweep label states as this run leaves them.
  const names = (i) => (i.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
  const converged = new Set([...result.stale, ...result.deadClaims]);
  const armed = open.filter((i) => readyLabelOn(i) && !converged.has(i.number)).length;
  const running = open.filter((i) => names(i).includes(AGENT_RUNNING_LABEL) && !converged.has(i.number)).length;
  const needsHuman = open.filter((i) => names(i).includes(NEEDS_HUMAN_LABEL)).length + converged.size;
  log(`health: ${result.open} open dispatch issue(s) — ${armed} armed, ${running} running, ${needsHuman} needs-human; `
    + `this run escalated ${result.stale.length}, reclaimed ${result.deadClaims.length}, re-armed ${result.rearmed.length}`);
  return result;
}

// WHICH SWEEP is the repo's dispatch mode (tasks-dispatch DESIGN §14): the two
// mechanisms have disjoint issue families, so a janitor that ran both sweeps would
// find nothing in one of them and a janitor that ran the wrong one would find
// nothing at all — and report a clean bill of health either way. One repo, one
// mechanism, one sweep.
export async function main() {
  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the janitor cannot read or write issues');
  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
  const config = loadConfig(root);
  if (config.taskScheduler?.dispatch === 'queue') {
    const { sweepQueue } = await import('./queue-sweep.mjs');
    const { discoverTasks } = await import('../../../../engine/scheduler/discover.mjs');
    const { tasks } = await discoverTasks(root, config);
    await sweepQueue(makeGh(), repo, new Date(), { tasks, log });
    return;
  }
  await sweep(makeGh(), repo, new Date());
}

// Run only when invoked directly (the scheduler's `node worker.mjs`), never on import.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => { console.error(`task-janitor failed: ${e.message}`); process.exit(1); });
}

